import React, { useCallback, useContext } from 'react';
import { FormattedMessage } from 'react-intl';

import { ArrowLeftIcon, ArrowRightIcon } from '@dynatrace/strato-icons';

import { useTableUserActionsContext } from './useTableUserActionsContext.js';
import { Menu } from '../../../../navigation/menu/Menu.js';
import { DataTableContext } from '../../../contexts/DataTableContext.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import type { ColumnMinInstance } from '../../../types/internal-table-types.js';
import {
  getDisableMoveLeftAndRight,
  changeColumnOrder,
} from '../../../utils/column-order-utils.js';

/**
 * DataTable column actions menu item for changing the order of the column.
 *
 * @returns ColumnOrder component or null if no columns are defined
 */
export const ColumnOrder = () => {
  const {
    onColumnOrderChange,
    allOrderingColumns,
    visibleOrderingColumns = [],
  } = useContext(DataTableContext);
  const tableActionContext = useTableUserActionsContext();
  const currentColumn = tableActionContext?.column as ColumnMinInstance;

  // index of the column or the first column with the respective header column
  const currentIndex = allOrderingColumns?.findIndex(
    (col) => col.id === currentColumn.id || col.parent?.id === currentColumn.id,
  );

  const { disableMoveLeft, disableMoveRight } = getDisableMoveLeftAndRight(
    currentColumn,
    visibleOrderingColumns,
  );

  const handleColumnMoving = useCallback(
    (direction: 'left' | 'right') => {
      const columnsReordered = changeColumnOrder(
        direction,
        currentIndex ?? 0,
        currentColumn,
        allOrderingColumns,
      );

      const newColumnOrder = columnsReordered?.map((column) => column.id);
      onColumnOrderChange(newColumnOrder ?? []);
    },
    [allOrderingColumns, currentColumn, currentIndex, onColumnOrderChange],
  );

  if (!allOrderingColumns) {
    return null;
  }

  return (
    <>
      <Menu.Item
        disabled={disableMoveLeft}
        onSelect={() => handleColumnMoving('left')}
      >
        <Menu.ItemIcon>
          <ArrowLeftIcon />
        </Menu.ItemIcon>
        <FormattedMessage {...dataTableMessages.moveColumnLeftLabel} />
      </Menu.Item>
      <Menu.Item
        disabled={disableMoveRight}
        onSelect={() => handleColumnMoving('right')}
      >
        <Menu.ItemIcon>
          <ArrowRightIcon />
        </Menu.ItemIcon>
        <FormattedMessage {...dataTableMessages.moveColumnRightLabel} />
      </Menu.Item>
    </>
  );
};

ColumnOrder['displayName'] = 'TableUserActions.ColumnOrder';
